import{_ as i,a,c as t,ac as n}from"./chunks/framework.BSuaGltH.js";const f=JSON.parse('{"title":"思考与方法：复盘记录与行动收敛","description":"以30分钟讨论超时案例练习事后偏差、具体行动和复盘证据边界。","frontmatter":{"title":"思考与方法：复盘记录与行动收敛","description":"以30分钟讨论超时案例练习事后偏差、具体行动和复盘证据边界。","showdocs":{"topics":[{"id":"thinking","title":"思考与方法","link":"/topics/thinking/"}],"kind":"偏差与后续行动","scope":"general","audience":"general","group":"学习与记录","seriesTitle":"思考与方法：把问题写成可检验判断","summary":"以30分钟讨论超时案例练习事后偏差、具体行动和复盘证据边界。","status":"active","related":[{"title":"思考与方法：把问题写成可检验判断","link":"/life/thinking/analysis/methods","kind":"问题与证据方法","scope":"general","audience":"general"},{"title":"思考与方法：分析框架、定义与证据边界","link":"/life/thinking/analysis/frameworks","kind":"框架及面试复习材料","scope":"general","audience":"general"},{"title":"思考与方法：一次虚构讨论改进案例","link":"/life/thinking/reference/case-study","kind":"案例推演与复盘","scope":"general","audience":"general"}],"prev":{"text":"思考与方法：分析框架、定义与证据边界","link":"/life/thinking/analysis/frameworks"},"next":false},"layout":"ReadingPage","sidebar":false,"aside":false,"prev":{"text":"思考与方法：分析框架、定义与证据边界","link":"/life/thinking/analysis/frameworks"},"next":false},"headers":[],"relativePath":"life/thinking/retrospective/retrospective.md","filePath":"life/thinking/retrospective/retrospective.md"}'),r={name:"life/thinking/retrospective/retrospective.md"};function s(l,e,o,c,d,h){return a(),t("div",null,[...e[0]||(e[0]=[n('<h1 id="思考与方法-复盘记录与行动收敛" tabindex="-1">思考与方法：复盘记录与行动收敛 <a class="header-anchor" href="#思考与方法-复盘记录与行动收敛" aria-label="Permalink to &quot;思考与方法：复盘记录与行动收敛&quot;">​</a></h1><p>先读<a href="/life/thinking/reference/case-study">四人30分钟讨论案例</a>：A保留六题自由发言，B选两题轮流发言。B的原预算为2分钟说明、两题各10分钟、6分钟汇总和2分钟机动，虚构结果为32分钟。本页据此练习事后偏差与下一轮行动；这些不是用户经历。</p><h2 id="hindsight" tabindex="-1">事后偏差 <a class="header-anchor" href="#hindsight" aria-label="Permalink to &quot;事后偏差 {#hindsight}&quot;">​</a></h2><p>思考 事后偏差会把结果已知当成当时必然。行动前保存“为什么选B、预计哪里失败、什么证据会改变判断”，结果后才有基准。一个好结果可能伴随侥幸，一个坏结果也可能来自合理决策面对不利条件。</p><p>练习：B超时2分钟是否证明当初应选A？答案不成立，因为没有A在同样条件下的结果。可说B未达到时长目标，并提出缩短汇总的新测试；不能把未实施的A当作肯定更好的对照。</p><h2 id="action" tabindex="-1">行动收敛 <a class="header-anchor" href="#action" aria-label="Permalink to &quot;行动收敛 {#action}&quot;">​</a></h2><p>思考 行动收敛每轮优先挑一个可观察改变，并写触发与退出条件。本例下一次把汇总缩短2分钟，主持在第24分钟开始汇总；若问题讨论仍未结束，就记为轮次控制失败，保留未讨论问题到下次。</p><p>题：“以后加强沟通”如何改写？参考：“下次开始前逐人确认两题是否看懂；不懂时允许先提澄清问题；记录准备阶段用了几分钟。”它有具体动作、时点和观察量。若行动依赖未获同意的人配合，先记录依赖未满足，不替别人承诺。</p><h2 id="limits" tabindex="-1">方法适用边界 <a class="header-anchor" href="#limits" aria-label="Permalink to &quot;方法适用边界 {#limits}&quot;">​</a></h2><p>思考 方法适用边界要求把决策框架、经验材料和专业结论分开。这套方法用于普通学习活动的记录练习，不生成医疗、财务或人事结论，也不把虚构小组结果当作用户经历。</p><p>题：可以从一次讨论记录推断某人的能力差吗？答案不能，样本小且条件不一致，最多记录当次可见行为。对于不可逆或影响他人的决策，先澄清权限与必要证据；复盘的目的在于改进可控过程，避免把记录变成未核实的人物评价。</p>',11)])])}const k=i(r,[["render",s]]);export{f as __pageData,k as default};
